import{HIRAKUD_DATA}from"./hirakud-data.js";function initTheme(){const t=document.getElementById("theme-toggle");t&&t.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark"),t.textContent=e?"🌙":"☀️"})}function initNavbar(){const t=document.getElementById("menu-toggle"),e=document.getElementById("nav-menu");t&&e&&t.addEventListener("click",()=>{const n="true"===t.getAttribute("aria-expanded");t.setAttribute("aria-expanded",!n),e.classList.toggle("active")})}function renderStats(){const t=document.getElementById("stats-grid");t&&HIRAKUD_DATA.stats&&(t.innerHTML=HIRAKUD_DATA.stats.map(t=>`\n        <div class="stat-card">\n            <span class="stat-icon">${t.icon}</span>\n            <div class="stat-value">${t.value}</div>\n            <div class="stat-label">${t.label}</div>\n        </div>\n    `).join(""))}function renderHistory(){const t=document.getElementById("history-title"),e=document.getElementById("history-content");t&&(t.textContent=HIRAKUD_DATA.reservoirHistory.title),e&&(e.textContent=HIRAKUD_DATA.reservoirHistory.content)}function renderRamsar(){const t=document.getElementById("ramsar-title"),e=document.getElementById("ramsar-content");t&&(t.textContent=HIRAKUD_DATA.ramsarSite.title),e&&(e.textContent=HIRAKUD_DATA.ramsarSite.content)}function renderWaterManagement(){const t=document.getElementById("water-title"),e=document.getElementById("water-content");t&&(t.textContent=HIRAKUD_DATA.waterManagement.title),e&&(e.textContent=HIRAKUD_DATA.waterManagement.content)}function renderBirdlife(){const t=document.getElementById("birdlife-title"),e=document.getElementById("birdlife-content"),n=document.getElementById("birdlife-facts");t&&(t.textContent=HIRAKUD_DATA.birdlife.title),e&&(e.textContent=HIRAKUD_DATA.birdlife.content),n&&HIRAKUD_DATA.birdlife.facts&&(n.innerHTML=HIRAKUD_DATA.birdlife.facts.map(t=>`<div class="fact-bullet">🦆 ${t}</div>`).join(""))}function renderFisheries(){const t=document.getElementById("fisheries-title"),e=document.getElementById("fisheries-content");t&&(t.textContent=HIRAKUD_DATA.fisheries.title),e&&(e.textContent=HIRAKUD_DATA.fisheries.content)}function renderBiodiversity(){const t=document.getElementById("biodiversity-title"),e=document.getElementById("biodiversity-content");t&&(t.textContent=HIRAKUD_DATA.biodiversity.title),e&&(e.textContent=HIRAKUD_DATA.biodiversity.content)}function renderMapHotspots(){const t=document.getElementById("hotspots-list");t&&HIRAKUD_DATA.hotspots&&(t.innerHTML=HIRAKUD_DATA.hotspots.map((t,e)=>`\n        <button class="spot-btn ${0===e?"active":""}" data-id="${t.id}">\n            <span class="spot-name">${t.name}</span>\n        </button>\n    `).join(""),showHotspotDetail(HIRAKUD_DATA.hotspots[0]),t.addEventListener("click",t=>{const e=t.target.closest(".spot-btn");if(!e)return;const n=e.getAttribute("data-id"),i=HIRAKUD_DATA.hotspots.find(t=>t.id===n);document.querySelectorAll(".spot-btn").forEach(t=>t.classList.remove("active")),e.classList.add("active"),i&&showHotspotDetail(i)}))}function showHotspotDetail(t){const e=document.getElementById("hotspot-detail");e&&(e.innerHTML=`\n        <h3 style="margin: 0 0 0.5rem; color: #0ea5e9; font-size: 1.5rem;">${t.name}</h3>\n        <p style="color: var(--hirakud-text-sub); line-height: 1.6; margin-bottom: 1.25rem;">${t.desc}</p>\n        <div style="font-family: monospace; font-size: 0.85rem; color: #94a3b8; background: rgba(0,0,0,0.2); padding: 0.5rem 0.85rem; border-radius: 0.5rem;">Coordinates: ${t.lat}° N, ${t.lng}° E</div>\n    `)}function renderGallery(){const t=document.getElementById("gallery-grid");t&&HIRAKUD_DATA.gallery&&(t.innerHTML=HIRAKUD_DATA.gallery.map(t=>`\n        <div class="gallery-card">\n            <img src="${t.url}" alt="${t.title}" loading="lazy" />\n            <div class="gallery-info">\n                <h4>${t.title}</h4>\n                <p>${t.caption}</p>\n            </div>\n        </div>\n    `).join(""))}function renderFacts(){const t=document.getElementById("facts-grid");t&&HIRAKUD_DATA.facts&&(t.innerHTML=HIRAKUD_DATA.facts.map(t=>`<div class="trivia-box">💡 ${t}</div>`).join(""))}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavbar(),renderStats(),renderHistory(),renderRamsar(),renderWaterManagement(),renderBirdlife(),renderFisheries(),renderBiodiversity(),renderMapHotspots(),renderGallery(),renderFacts()});